// CSD_RATIONALE_BEGIN
// CloseSpanWithinBudget strategy for symbolic GSM.
//
// Root-cause analysis of attempt 3 failures:
//
// (A) TINY SPANS (35/49, mode_B): The strategy detected every "<<" the model
//     generated during free reasoning — including intermediate spans like
//     "<<n1>>" or "<<p2>>" — and entered constrained mode there. The constrained
//     phase then closed immediately on the first parser-complete token (median
//     span = 1 token). The rollback-to-complete approach found the last
//     complete point, which was trivially after 1 token.
//
// (B) UNCLOSED SPANS (7/49, modes A/I): When AdaptiveConstrainedStep returned
//     EOS inside a span AND steps had already reached maxSteps, the emergency-
//     close guard `steps < maxSteps` was false, leaving the span open. Also,
//     the "final_span_unclosed" pattern (model opens << right at the budget
//     limit) left no room for constrained content.
//
// (C) REPETITION LOOPS (mode from rollouts): Inside the constrained span the
//     model generated "10-10-10-..." exhausting the budget without closure.
//
// Fixes applied:
//   1. Phase 1 (free reasoning) deliberately does NOT detect "<<". All
//      intermediate <<>> spans the model generates go through unconstrained
//      generation — they are fast and the evaluator uses only the LAST span.
//      This eliminates false triggers on intermediate spans.
//   2. Phase 2 FORCES a final "<<" via OpenConstrainedSpan after the free
//      phase ends. The generated context then ends with "...reasoning... <<"
//      which cues the model to produce the final symbolic expression.
//   3. Phase 3 uses CloseSpanWithinBudget with ALL remaining budget. This
//      helper generates forward (dead-end-aware), tracks the LONGEST complete
//      parse point throughout the budget, and emits ">>" there. It avoids
//      premature single-token closure and handles repetition by tracking the
//      best complete prefix, not just the first.
//
// Budget allocation (maxSteps=900):
//   freeLimit = 600 steps for free reasoning
//   Phase 2   =   1 step  for forced "<<"
//   Phase 3   = 299 steps for CloseSpanWithinBudget
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//    Phase 1 (free loop, no << detection):
//      The loop guard includes !insideConstrainedOut. We never assign
//      insideConstrainedOut := true inside the loop body. Therefore the
//      implication is vacuously true throughout Phase 1.
//
//    Phase 2 (OpenConstrainedSpan):
//      Guarded by !insideConstrainedOut. OpenConstrainedSpan sets
//      insideConstrainedOut := true and currentConstrainedOut := [].
//      parser.IsValidPrefix([]) holds by method precondition. ✓
//
//    Phase 3 (CloseSpanWithinBudget):
//      By postcondition:
//        !insideOut ==> currentOut == []                (trivially valid)
//        insideOut  ==> parser.IsValidPrefix(currentOut)
//      Both branches satisfy the invariant. ✓
//
//    If entry has insideConstrained = true:
//      Phase 1 and Phase 2 are skipped (guard !insideConstrainedOut is false).
//      Phase 3 runs immediately; same CloseSpanWithinBudget argument applies. ✓
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//
//    Phase 1: UnconstrainedStep costs 1 step; on non-EOS appends exactly 1
//      visible token; on EOS appends 0. Either way
//      |generated| - |generatedPrefix| grows by at most 1 while steps grows by
//      exactly 1. Invariant preserved each iteration.
//
//    Phase 2: OpenConstrainedSpan appends exactly "<<" (1 visible token) and
//      steps is incremented by 1. Net growth is equal. Invariant preserved.
//
//    Phase 3: CloseSpanWithinBudget guarantees
//        |generatedOut| <= |generated_before| + remaining.
//      We set steps := steps_before + remaining (= maxSteps). So
//        |generatedOut| <= |generatedPrefix| + steps_before + remaining
//                        = |generatedPrefix| + maxSteps = |generatedPrefix| + steps_after.
//      Invariant preserved. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the math word problem step by step. " +
  "Reason carefully and identify all relevant quantities and how they combine. " +
  "At the very end, wrap ONLY the single complete final symbolic expression in << >>. " +
  "Use the exact variable names from the problem. " +
  "The expression MUST combine all relevant variables with arithmetic (+, -, *, /, //, %, int()). " +
  "Do not write a single variable name alone as the final answer.");

var steps: nat := 0;
var freeLimit: nat := if maxSteps > 300 then maxSteps - 300 else maxSteps / 2;

// Phase 1: Pure unconstrained reasoning.
// Deliberately no << detection: intermediate spans the model generates
// are allowed through unconstrained so we do not enter constrained mode
// prematurely on them. The evaluator uses only the LAST <<>> span.
while steps < freeLimit && !insideConstrainedOut
  invariant 0 <= steps <= freeLimit
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeLimit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
}

// Phase 2: Force the final answer span open.
// After the free reasoning phase the model context ends with the full chain-
// of-thought; appending "<<" cues it to produce the final symbolic expression.
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate and close the constrained final-answer span.
// CloseSpanWithinBudget generates forward (dead-end-aware), tracks the LONGEST
// complete parse point seen within the budget, and emits ">>" there.
// This avoids both premature single-token closure and repetition loops.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + remaining;
}

cost := steps;

